(() => {
  const DOCS = [{"k":"contact email reach hire hiring available availability freelance rate rates price cost quote job role work together","a":"You can reach Saad through the [contact form](/#contact) or at mehmoodsaad042@gmail.com — he replies within one business day. He's open to full-time or contract AI/ML roles and freelance projects; for rates and timing, send a short brief through the form."},{"k":"who about saad background education university study degree comsats location where based pakistan islamabad","a":"Saad Mehmood is an AI/ML Engineer based in Islamabad, Pakistan, working remotely worldwide. He's studying for a BS Artificial Intelligence, COMSATS University Islamabad, and founded OQVERA, an AI automation and agents studio."},{"k":"skills stack tech technologies tools languages python framework know","a":"Main skills: **AI engineering** — LangGraph, LangChain, RAG, Tool calling, Structured outputs, Pydantic; **Retrieval & data** — FAISS, ChromaDB, Sentence-Transformers, Tavily, PostgreSQL, SQLite; **Deep learning & vision** — PyTorch, TensorFlow / Keras, ViT & ViViT, LoRA fine-tuning, U-Net, CNN-LSTM; **Backend & infra** — Python, FastAPI, Flask, Django REST, Celery, Docker; **Frontend** — React, Next.js, Vite, Tailwind, three.js, Streamlit; **Automation & voice** — Make, n8n, Zapier, Vapi voice agents, Webhooks, CRM integrations."},{"k":"experience work history omni digitals oqvera founder job","a":"**Founder, OQVERA**, AI automation & agent studio (2026 – now); **Web & App Developer**, Omni Digitals (2024 – now); **BS Artificial Intelligence**, COMSATS University Islamabad (2023 – 2027)."},{"k":"deeptruth deepfake and synthetic-media detection platform pytorch vivit vit-b/16 lora mtcnn fastapi celery redis sqlite server-sent events next.js 16 chrome extension computer vision machine learning deeptruth","a":"**DeepTruth** — Upload a video or image and get a verdict on whether it was manipulated, from an ensemble of fine-tuned vision transformers running behind a queued API, a web console and a browser extension. Read the [case study](/case-studies/deeptruth.html). Code: https://github.com/saad7420/Deep-Truth---DeepFake-Media-Detection"},{"k":"dealership ai calling agent voice agent and sales automation for national motors vapi voice ai make google sheets webhooks crm apis ai agents automation dealership ai agent","a":"**Dealership AI Calling Agent** — An inbound voice agent for a car dealership that talks to callers, checks live inventory, qualifies the lead, books a test drive and triggers follow-up automatically. Read the [case study](/case-studies/dealership-ai-agent.html). Ask for a demo through the [contact form](/#contact)."},{"k":"content creation pipeline agentic writing workflow with a quality gate, built on langgraph langgraph langchain groq llama 3.3 70b pydantic python ai agents content creation pipeline","a":"**Content Creation Pipeline** — Turns a topic into a researched, outlined, drafted, reviewed and publish-ready post — and sends weak drafts back for revision before anything is published. Read the [case study](/case-studies/content-creation-pipeline.html). Code: https://github.com/saad7420/Content-Creation-Pipeline-using-LangGraph"},{"k":"langgraph tool-using chatbot stateful agent with six live tools and persistent threads langgraph langchain groq llama 3.3 70b sqlite checkpointer streamlit duckduckgo openweather alpha vantage ai agents langgraph tool agent","a":"**LangGraph Tool-Using Chatbot** — A chat agent that decides when to search the web, check a stock, get the weather, do maths or convert units — and remembers every conversation thread across restarts. Read the [case study](/case-studies/langgraph-tool-agent.html). Code: https://github.com/saad7420/Chatbot-based-on-Langgraph · Live demo: https://saad7420-chatbot-based-on-langgraph-app-utzuat.streamlit.app/"},{"k":"ai customer support platform production-style support chatbot api with sessions and tests fastapi langchain groq llama 3.1 8b sqlalchemy sqlite pydantic v2 streamlit docker compose pytest ai agents ai customer support platform","a":"**AI Customer Support Platform** — A FastAPI service that runs support conversations with memory, stores every session and message, rate-limits clients and ships with Docker and a 90% coverage test gate. Read the [case study](/case-studies/ai-customer-support-platform.html). Code: https://github.com/saad7420/AI-CUSTOMER-SUPPORT-CHATBOT"},{"k":"enterprise document intelligence hybrid research engine that routes between internal documents and the live web fastapi chromadb openai embeddings tavily search llama 3.2 (hf router) gpt-4o mini pydantic streamlit rag & documents ai agents hybrid research engine","a":"**Enterprise Document Intelligence** — Ask a question and an LLM router decides whether to search internal documents, the web, or both — then writes a report where every fact carries a numbered citation. Read the [case study](/case-studies/hybrid-research-engine.html). Code: https://github.com/saad7420/Enterprise-Document-Intelligence-Platform"},{"k":"intelligent document processing turn pdfs and word files into structured, validated data fastapi pymupdf python-docx llama 3.2 (hf router) pydantic sqlalchemy streamlit rag & documents intelligent document processing","a":"**Intelligent Document Processing** — Upload a PDF, DOCX or text file and get back a summary, key terms, named entities and action items with owners and due dates — validated against a schema and stored. Read the [case study](/case-studies/intelligent-document-processing.html). Code: https://github.com/saad7420/Intelligent-Document-Processing-Pipeline"},{"k":"product manual assistant rag assistant that answers from technical documentation, with page citations langchain faiss all-minilm-l6-v2 pypdf hugging face streamlit rag & documents product manual assistant","a":"**Product Manual Assistant** — Engineers ask in plain language about installation, ports or troubleshooting, and get an answer grounded in the manual with the exact source file and page. Read the [case study](/case-studies/product-manual-assistant.html). Code: https://github.com/saad7420/Product-Manual-Assistant"},{"k":"smart form filler agent that turns a sentence into a validated registration form python pydantic v2 regex extraction langchain structured output (drop-in) groq ai agents smart form filler","a":"**Smart Form Filler** — Describe an event registration in plain words; the agent extracts the fields, asks one clear question about anything missing, and only emits JSON once it passes validation. Read the [case study](/case-studies/smart-form-filler.html). Code: https://github.com/saad7420/Event-Form-Filling-powered-by-pydantic-output-parser-and-RegEx"},{"k":"smart faq chatbot retrieval-first faq bot that refuses to invent answers sentence-transformers faiss all-minilm-l6-v2 python streamlit rag & documents smart faq chatbot","a":"**Smart FAQ Chatbot** — Searches a knowledge base with embeddings and answers from what it finds — and falls back to a contact message when nothing is relevant enough. Read the [case study](/case-studies/smart-faq-chatbot.html). Code: https://github.com/saad7420/Smart-FAQ-Chatbot-RAG-Based-System"},{"k":"image colorization u-net that brings colour back to black-and-white photos pytorch u-net cie lab colour space scikit-image tkinter kaggle computer vision image colorization","a":"**Image Colorization** — A PyTorch U-Net trained to predict colour channels from a grayscale image, wrapped in a desktop app for loading, colourising and saving photos. Read the [case study](/case-studies/image-colorization.html). Code: https://github.com/saad7420/Image-Colorization-using-PyTorch-with-U-Net-Architecture-"},{"k":"driving decisions with cnn-lstm webcam model that decides stop, continue or slow down from a sequence of frames tensorflow / keras cnn lstm opencv numpy kaggle computer vision machine learning cnn lstm driving","a":"**Driving Decisions with CNN-LSTM** — A CNN reads each camera frame, an LSTM reads the last five, and the system decides an action in real time — steadier than judging one frame at a time. Read the [case study](/case-studies/cnn-lstm-driving.html). Code: https://github.com/saad7420/Autonomous-Driving-Logic-via-CNN-LSTM-Fusion-with-Keras"},{"k":"nexora webar saas for publishing 3d products in augmented reality typescript react 18 express drizzle orm postgresql stripe blender pipeline tailwind web & ar nexora webar","a":"**Nexora WebAR** — Businesses upload 3D models, the platform converts them for web and iPhone AR, and customers open them in AR from a short link — with workspaces, teams, analytics and subscriptions. Read the [case study](/case-studies/nexora-webar.html). Code: https://github.com/saad7420/Nexora-WebAR"},{"k":"webar model viewer mern app for uploading, viewing and sharing 3d models in ar mongodb express react node.js three.js react three fiber aws s3 jwt qr codes web & ar webar viewer","a":"**WebAR Model Viewer** — Upload a 3D model, preview it in the browser, launch it in AR and share it with a QR code — with accounts, an admin dashboard and view analytics. Read the [case study](/case-studies/webar-viewer.html). Code: https://github.com/saad7420/WebAR"},{"k":"emotion classifier cnn that tells happy from sad faces tensorflow keras opencv kaggle computer vision machine learning emotion classifier","a":"**Emotion Classifier** — A TensorFlow CNN trained on a Kaggle dataset I published, with data cleaning, a 70/20/10 split, and precision, recall and accuracy checks on the held-out set. Code: https://github.com/saad7420/Emotion-Classifier-Model-based-on-CNN-using-Tensorflow"},{"k":"california house price predictor regression model with a streamlit app scikit-learn pandas joblib streamlit machine learning house price prediction","a":"**California House Price Predictor** — Linear regression on the California housing data with cleaning, encoding and scaling; R² 0.65 and MAE about $50k on the test split, served through a Streamlit form. Code: https://github.com/saad7420/Price-Prediction-with-Linear-Regression"},{"k":"resume screening bot ranks cvs against a job description flask scikit-learn tf-idf pymupdf machine learning resume screening bot","a":"**Resume Screening Bot** — Extracts text from uploaded PDF résumés and ranks them by TF-IDF cosine similarity to the job description, in a Flask web app. Code: https://github.com/saad7420/Resume-Screening-Bot-based-on-NLP-Flask"},{"k":"task summarizer flask app on gemini 2.0 flash flask gemini api python ai agents text summarizer","a":"**Task Summarizer** — Paste a long task or brief and get a clear summary back from Gemini 2.0 Flash, through a minimal Flask interface. Code: https://github.com/saad7420/Text-Summerizer-using-Flask-based-on-Gemini-api"},{"k":"connected operations automation business workflows across tools and apis n8n make webhooks apis automation connected operations","a":"**Connected Operations Automation** — Workflow automation that moves data between CRMs, databases, forms and AI steps through n8n, Make and webhooks, so routine hand-offs happen without anyone copying information. Ask for a demo through the [contact form](/#contact)."},{"k":"event manager django rest + react app django rest jwt postgresql react web & ar event manager","a":"**Event Manager** — Create and manage events with JWT authentication, a Django REST API on PostgreSQL and a React frontend that separates upcoming and past events. Code: https://github.com/saad7420/Event-Manager-Django-Based-Project"},{"k":"cais website comsats ai society react 19 vite express mongodb web & ar cais website","a":"**CAIS Website** — Website for the COMSATS Artificial Intelligence Society with events and member sign-ups, built on React 19 with an Express and MongoDB backend. Code: https://github.com/saad7420/CAIS-Website"},{"k":"weather dashboard react + openweather react vite openweather api web & ar weather dashboard","a":"**Weather Dashboard** — Search any city and see current conditions, built with React hooks and the OpenWeather API. Code: https://github.com/saad7420/Weather-Dashboard-React-Web-App"},{"k":"c++ systems projects student database, gpa calculator, ticket booking c++ oop file i/o web & ar cpp college projects","a":"**C++ Systems Projects** — Early object-oriented C++ programs that add, edit, store and delete records, calculate GPA and book movie tickets. Code: https://github.com/saad7420/CPP-CollegeProjects"}];
  const stop = new Set('a an the is are was what which who how does do did can could he his him saad me tell about of for to in on with and or any has have you your i it this that there show give'.split(' '));
  const toks = s => (s.toLowerCase().match(/[a-z0-9.+#]+/g) || []).filter(t => !stop.has(t) && t.length > 1);
  window.SM_LOCAL_ANSWER = q => {
    const qt = toks(q); if (!qt.length) return "Ask me about Saad's projects, skills, experience or how to work with him.";
    let best = [];
    for (const d of DOCS){ const dt = new Set(toks(d.k)); let s = 0; for (const t of qt){ if (dt.has(t)) s += 1; else if ([...dt].some(x => x.length > 3 && (x.startsWith(t) || t.startsWith(x)))) s += .5; } if (s > 0) best.push([s, d]); }
    best.sort((a, b) => b[0] - a[0]);
    if (!best.length || best[0][0] < 1) return "I don't have that in my notes. You can ask Saad directly through the [contact form](/#contact) or at mehmoodsaad042@gmail.com.";
    const top = best.filter(b => b[0] >= best[0][0] * .8).slice(0, 3).map(b => b[1].a);
    return top.join('\n\n');
  };
})();
